prolog:
#Region @DOC
# ====================================================================================================
# }IDE.Version.Copy -- copy one version into another, across every cube that carries the version
# dimension. One generic core process for any TM1 model; no Bedrock.
# ====================================================================================================
#
# DESCRIPTION
#   Copies the data of version pSource into version pTarget in every cube that has the version
#   dimension (less pExcludeCubes). Two kinds of copy:
#     static       a frozen copy: every stored and rule-calculated value is written into the target,
#                  and the target is put under pStaticParent (e.g. Non-Calculating) so the rule guard
#                  [] = N: IF(ELPAR(<dim>, !<dim>, 1) @= 'Non-Calculating', STET, CONTINUE);
#                  stops the rules recalculating it. Use for a month-end forecast snapshot.
#     calculating  a working copy: only input cells are copied (rule values are skipped) and the
#                  target is NOT under pStaticParent, so the rules rebuild everything from the copied
#                  inputs. Use to seed a scenario (e.g. Downside from Forecast).
#
# USE CASES
#   Month-end snapshot   pSource=Forecast  pTarget=FCST 2026-04  pMode=new  pType=static
#   Re-run a snapshot    as above with pMode=replace (the target is cleared first)
#   Seed a scenario      pSource=Forecast  pTarget=Downside  pMode=replace  pType=calculating
#
# HOW IT WORKS
#   Parent call (pCube blank)
#     Prolog  checks the parameters, creates or prepares the target version (type and status
#             attributes, parent), never touching the source.
#     Epilog  calls this process once per cube (pCube set) and fails the whole copy if any cube
#             fails -- there is no silent partial copy.
#   Child call (pCube set)
#     Prolog  builds a source view (pSource only, leaf cells, zeros skipped) and a target view, zeroes
#             the target slice in that cube, and makes the source view this call's data source.
#     Data    writes each source cell to the same coordinates in pTarget.
#     Epilog  removes the temporary views and subsets.
#
# NOTES / GOOD TO KNOW
#   * Cells a rule still owns in the target are skipped (CellIsUpdateable). That happens only in a cube
#     whose rules have no static-version guard; there the rules calculate those cells in the target
#     from its copied inputs. House standard: every rule file starts with the guard.
#   * A static copy refuses to run unless pTarget is under pStaticParent, so a "static" copy can never
#     quietly land in a calculating version.
#   * Transaction logging is switched off per cube while copying, and back on after.
#   * Cubes with 2 to 8 dimensions are supported.
#   * Blank pVersionDim / pStaticParent / pInputCubes / pExcludeCubes / pTypeAttr / pStatusAttr are
#     filled from cube SYS Settings (row pApp, then All) when that cube exists.
#   * Called from another process, it ends normally (no ProcessQuit), so the caller is not flagged.
#   * Hidden process (leading }): call it from a model wrapper (e.g. WFP Snapshot) or the IDE's Core TI
#     action / MCP copy_version tool, not directly by end users.
#
# CALL THIS PROCESS
#   nRet = ExecuteProcess( '}IDE.Version.Copy',
#      'pSource', 'Forecast', 'pTarget', 'FCST 2026-04', 'pMode', 'new', 'pType', 'static',
#      'pVersionDim', 'WFP Version', 'pStaticParent', 'Non-Calculating',
#      'pExcludeCubes', 'WFP Control', 'pStatus', 'Approved' );
#   IF( nRet <> ProcessExitNormal() ); ProcessError; ENDIF;
#
# SOURCE  core-ti/version-copy/process.json in the TM1 IDE repo (this server copy is the runtime copy)
# ====================================================================================================
#EndRegion @DOC
cThis = GetProcessName();
# Model settings: application row, then All, then parameter defaults.
IF(CubeExists('SYS Settings') = 1);
  sTmp = CellGetS('SYS Settings', pApp, 'Version Dimension', 'Text');
  IF(sTmp @= ''); sTmp = CellGetS('SYS Settings', 'All', 'Version Dimension', 'Text'); ENDIF;
  IF(sTmp @<> '' & pVersionDim @= ''); pVersionDim = sTmp; ENDIF;
  sTmp = CellGetS('SYS Settings', pApp, 'Version Static Parent', 'Text');
  IF(sTmp @= ''); sTmp = CellGetS('SYS Settings', 'All', 'Version Static Parent', 'Text'); ENDIF;
  IF(sTmp @<> '' & pStaticParent @= ''); pStaticParent = sTmp; ENDIF;
  sTmp = CellGetS('SYS Settings', pApp, 'Version Input Cubes', 'Text');
  IF(sTmp @= ''); sTmp = CellGetS('SYS Settings', 'All', 'Version Input Cubes', 'Text'); ENDIF;
  IF(sTmp @<> '' & pInputCubes @= ''); pInputCubes = sTmp; ENDIF;
  sTmp = CellGetS('SYS Settings', pApp, 'Version Exclude Cubes', 'Text');
  IF(sTmp @= ''); sTmp = CellGetS('SYS Settings', 'All', 'Version Exclude Cubes', 'Text'); ENDIF;
  IF(sTmp @<> '' & pExcludeCubes @= ''); pExcludeCubes = sTmp; ENDIF;
  sTmp = CellGetS('SYS Settings', pApp, 'Version Type Attribute', 'Text');
  IF(sTmp @= ''); sTmp = CellGetS('SYS Settings', 'All', 'Version Type Attribute', 'Text'); ENDIF;
  IF(sTmp @<> '' & pTypeAttr @= ''); pTypeAttr = sTmp; ENDIF;
  sTmp = CellGetS('SYS Settings', pApp, 'Version Status Attribute', 'Text');
  IF(sTmp @= ''); sTmp = CellGetS('SYS Settings', 'All', 'Version Status Attribute', 'Text'); ENDIF;
  IF(sTmp @<> '' & pStatusAttr @= ''); pStatusAttr = sTmp; ENDIF;
ENDIF;
cVer = pVersionDim;
IF(cVer @= ''); ProcessError; ENDIF;
IF(pCube @= '');
  IF(pSource @= '' % pTarget @= '' % pSource @= pTarget);
    ProcessError;
  ENDIF;
  IF(DIMIX(cVer, pSource) = 0 % DTYPE(cVer, pSource) @<> 'N');
    ProcessError;
  ENDIF;
  IF(DIMIX(cVer, pTarget) > 0 & DTYPE(cVer, pTarget) @<> 'N');
    ProcessError;
  ENDIF;
  IF(pMode @<> 'new' & pMode @<> 'replace');
    ProcessError;
  ENDIF;
  IF(pType @<> 'static' & pType @<> 'calculating');
    ProcessError;
  ENDIF;
  IF(pMode @= 'new' & DIMIX(cVer, pTarget) > 0);
    ProcessError;
  ENDIF;
  IF(pMode @= 'replace' & DIMIX(cVer, pTarget) = 0);
    ProcessError;
  ENDIF;
  IF(pMode @= 'new');
    DimensionElementInsertDirect(cVer, '', pTarget, 'N');
  ENDIF;
  IF(pType @= 'static');
    IF(DIMIX('}ElementAttributes_' | cVer, pTypeAttr) > 0); AttrPutS('Static', cVer, pTarget, pTypeAttr); ENDIF;
    IF(pStaticParent @<> '' & DIMIX(cVer, pStaticParent) > 0);
      IF(ELISANC(cVer, pStaticParent, pTarget) = 0);
        DimensionElementComponentAddDirect(cVer, pStaticParent, pTarget, 1);
      ENDIF;
    ENDIF;
  ELSE;
    IF(DIMIX('}ElementAttributes_' | cVer, pTypeAttr) > 0); AttrPutS('Calculated', cVer, pTarget, pTypeAttr); ENDIF;
    IF(pStaticParent @<> '' & DIMIX(cVer, pStaticParent) > 0);
      IF(ELISANC(cVer, pStaticParent, pTarget) = 1);
        DimensionElementComponentDelete(cVer, pStaticParent, pTarget);
      ENDIF;
    ENDIF;
  ENDIF;
  IF(pStatus @= '');
    IF(pType @= 'static'); pStatus = 'Approved'; ELSE; pStatus = 'Working'; ENDIF;
  ENDIF;
  IF(DIMIX('}ElementAttributes_' | cVer, pStatusAttr) > 0); AttrPutS(pStatus, cVer, pTarget, pStatusAttr); ENDIF;
  # The cubes are copied in the Epilog, once the target version is prepared.
ENDIF;


# Child: pCube set
IF(pCube @<> '');
nSkip = 0;
nDimCount = 0; nD = 1;
WHILE(TabDim(pCube, nD) @<> '');
  nDimCount = nDimCount + 1; nD = nD + 1;
END;
IF(nDimCount < 2 % nDimCount > 8); ProcessError; ENDIF;
sSuf = NumberToString(INT(RAND() * 1000000000));
cSrcSub = cThis | ' Src ' | sSuf;
cTgtSub = cThis | ' Tgt ' | sSuf;
cSrcView = cThis | ' Src View ' | sSuf;
cTgtView = cThis | ' Tgt View ' | sSuf;
IF(SubsetExists(cVer, cSrcSub) = 1); SubsetDestroy(cVer, cSrcSub); ENDIF;
IF(SubsetExists(cVer, cTgtSub) = 1); SubsetDestroy(cVer, cTgtSub); ENDIF;
SubsetCreate(cVer, cSrcSub); SubsetElementInsert(cVer, cSrcSub, pSource, 1);
SubsetCreate(cVer, cTgtSub); SubsetElementInsert(cVer, cTgtSub, pTarget, 1);

IF(ViewExists(pCube, cSrcView) = 1); ViewDestroy(pCube, cSrcView); ENDIF;
ViewCreate(pCube, cSrcView);
ViewSubsetAssign(pCube, cSrcView, cVer, cSrcSub);
nD = 1;
WHILE(TabDim(pCube, nD) @<> '');
  IF(TabDim(pCube, nD) @<> cVer); ViewRowDimensionSet(pCube, cSrcView, TabDim(pCube, nD), 1); ENDIF;
  nD = nD + 1;
END;
ViewExtractSkipZeroesSet(pCube, cSrcView, 1);
ViewExtractSkipCalcsSet(pCube, cSrcView, 1);
IF(pType @= 'calculating'); ViewExtractSkipRuleValuesSet(pCube, cSrcView, 1); ELSE; ViewExtractSkipRuleValuesSet(pCube, cSrcView, 0); ENDIF;

IF(ViewExists(pCube, cTgtView) = 1); ViewDestroy(pCube, cTgtView); ENDIF;
ViewCreate(pCube, cTgtView);
ViewSubsetAssign(pCube, cTgtView, cVer, cTgtSub);
nD = 1;
WHILE(TabDim(pCube, nD) @<> '');
  IF(TabDim(pCube, nD) @<> cVer); ViewRowDimensionSet(pCube, cTgtView, TabDim(pCube, nD), 1); ENDIF;
  nD = nD + 1;
END;
ViewExtractSkipZeroesSet(pCube, cTgtView, 1);
ViewExtractSkipCalcsSet(pCube, cTgtView, 1);
IF(pType @= 'calculating'); ViewExtractSkipRuleValuesSet(pCube, cTgtView, 1); ELSE; ViewExtractSkipRuleValuesSet(pCube, cTgtView, 0); ENDIF;
CubeSetLogChanges(pCube, 0);
ViewZeroOut(pCube, cTgtView);
ViewDestroy(pCube, cTgtView);

DataSourceType = 'VIEW';
DatasourceNameForServer = pCube;
DatasourceNameForClient = pCube;
DatasourceCubeView = cSrcView;
ENDIF;

data:
# Cells a rule still owns in the target (a cube with no static-version guard) are not
# writable: skip them -- the rule calculates them from the copied inputs.
sV1 = IF(TabDim(pCube, 1) @= pVersionDim, pTarget, V1);
sV2 = IF(TabDim(pCube, 2) @= pVersionDim, pTarget, V2);
sV3 = IF(TabDim(pCube, 3) @= pVersionDim, pTarget, V3);
sV4 = IF(TabDim(pCube, 4) @= pVersionDim, pTarget, V4);
sV5 = IF(TabDim(pCube, 5) @= pVersionDim, pTarget, V5);
sV6 = IF(TabDim(pCube, 6) @= pVersionDim, pTarget, V6);
sV7 = IF(TabDim(pCube, 7) @= pVersionDim, pTarget, V7);
sV8 = IF(TabDim(pCube, 8) @= pVersionDim, pTarget, V8);
IF(Value_is_String = 1);
IF(nDimCount = 2); IF(CellIsUpdateable(pCube, sV1, sV2) = 1); CellPutS(SValue, pCube, sV1, sV2); ELSE; nSkip = nSkip + 1; ENDIF;
ELSEIF(nDimCount = 3); IF(CellIsUpdateable(pCube, sV1, sV2, sV3) = 1); CellPutS(SValue, pCube, sV1, sV2, sV3); ELSE; nSkip = nSkip + 1; ENDIF;
ELSEIF(nDimCount = 4); IF(CellIsUpdateable(pCube, sV1, sV2, sV3, sV4) = 1); CellPutS(SValue, pCube, sV1, sV2, sV3, sV4); ELSE; nSkip = nSkip + 1; ENDIF;
ELSEIF(nDimCount = 5); IF(CellIsUpdateable(pCube, sV1, sV2, sV3, sV4, sV5) = 1); CellPutS(SValue, pCube, sV1, sV2, sV3, sV4, sV5); ELSE; nSkip = nSkip + 1; ENDIF;
ELSEIF(nDimCount = 6); IF(CellIsUpdateable(pCube, sV1, sV2, sV3, sV4, sV5, sV6) = 1); CellPutS(SValue, pCube, sV1, sV2, sV3, sV4, sV5, sV6); ELSE; nSkip = nSkip + 1; ENDIF;
ELSEIF(nDimCount = 7); IF(CellIsUpdateable(pCube, sV1, sV2, sV3, sV4, sV5, sV6, sV7) = 1); CellPutS(SValue, pCube, sV1, sV2, sV3, sV4, sV5, sV6, sV7); ELSE; nSkip = nSkip + 1; ENDIF;
ELSEIF(nDimCount = 8); IF(CellIsUpdateable(pCube, sV1, sV2, sV3, sV4, sV5, sV6, sV7, sV8) = 1); CellPutS(SValue, pCube, sV1, sV2, sV3, sV4, sV5, sV6, sV7, sV8); ELSE; nSkip = nSkip + 1; ENDIF;
ENDIF;
ELSE;
IF(nDimCount = 2); IF(CellIsUpdateable(pCube, sV1, sV2) = 1); CellPutN(NValue, pCube, sV1, sV2); ELSE; nSkip = nSkip + 1; ENDIF;
ELSEIF(nDimCount = 3); IF(CellIsUpdateable(pCube, sV1, sV2, sV3) = 1); CellPutN(NValue, pCube, sV1, sV2, sV3); ELSE; nSkip = nSkip + 1; ENDIF;
ELSEIF(nDimCount = 4); IF(CellIsUpdateable(pCube, sV1, sV2, sV3, sV4) = 1); CellPutN(NValue, pCube, sV1, sV2, sV3, sV4); ELSE; nSkip = nSkip + 1; ENDIF;
ELSEIF(nDimCount = 5); IF(CellIsUpdateable(pCube, sV1, sV2, sV3, sV4, sV5) = 1); CellPutN(NValue, pCube, sV1, sV2, sV3, sV4, sV5); ELSE; nSkip = nSkip + 1; ENDIF;
ELSEIF(nDimCount = 6); IF(CellIsUpdateable(pCube, sV1, sV2, sV3, sV4, sV5, sV6) = 1); CellPutN(NValue, pCube, sV1, sV2, sV3, sV4, sV5, sV6); ELSE; nSkip = nSkip + 1; ENDIF;
ELSEIF(nDimCount = 7); IF(CellIsUpdateable(pCube, sV1, sV2, sV3, sV4, sV5, sV6, sV7) = 1); CellPutN(NValue, pCube, sV1, sV2, sV3, sV4, sV5, sV6, sV7); ELSE; nSkip = nSkip + 1; ENDIF;
ELSEIF(nDimCount = 8); IF(CellIsUpdateable(pCube, sV1, sV2, sV3, sV4, sV5, sV6, sV7, sV8) = 1); CellPutN(NValue, pCube, sV1, sV2, sV3, sV4, sV5, sV6, sV7, sV8); ELSE; nSkip = nSkip + 1; ENDIF;
ENDIF;
ENDIF;

epilog:
IF(pCube @= '');
  # Parent: the target is committed now -- copy each cube in its own child call.
  # A static copy must land in a version the rules treat as static; skipping unwritable
  # cells into a calculating version would leave a live, not a frozen, copy.
  IF(pType @= 'static' & pStaticParent @<> '');
    IF(ELISANC(cVer, pStaticParent, pTarget) = 0);
      LogOutput('ERROR', cThis | ': ' | pTarget | ' is not under ' | pStaticParent | ' -- refusing a static copy');
      ProcessError;
    ENDIF;
  ENDIF;
  nFail = 0; vFailed = '';
  nC = 1; nCC = DIMSIZ('}Cubes');
  WHILE(nC <= nCC);
    vCube = DIMNM('}Cubes', nC);
    IF(SUBST(vCube, 1, 1) @<> '}');
      nHas = 0; nD = 1;
      WHILE(TabDim(vCube, nD) @<> '');
        IF(TabDim(vCube, nD) @= cVer); nHas = 1; ENDIF;
        nD = nD + 1;
      END;
      IF(nHas = 1);
        vEx = '|' | pExcludeCubes | '|';
        vIn = '|' | pInputCubes | '|';
        IF(SCAN(vEx, '|' | vCube | '|') = 0 & (pType @= 'static' % pInputCubes @= '' % SCAN(vIn, '|' | vCube | '|') > 0));
          nRet = ExecuteProcess(cThis, 'pSource', pSource, 'pTarget', pTarget, 'pMode', pMode, 'pType', pType, 'pVersionDim', cVer, 'pStaticParent', pStaticParent, 'pInputCubes', pInputCubes, 'pExcludeCubes', pExcludeCubes, 'pStatus', pStatus, 'pTypeAttr', pTypeAttr, 'pStatusAttr', pStatusAttr, 'pCube', vCube, 'pApp', pApp);
          # a cube that fails to copy fails the whole copy -- never a silent partial snapshot
          IF(nRet <> ProcessExitNormal()); nFail = nFail + 1; vFailed = vFailed | vCube | '|'; ENDIF;
        ENDIF;
      ENDIF;
    ENDIF;
    nC = nC + 1;
  END;
  IF(nFail > 0);
    LogOutput('ERROR', cThis | ': ' | NumberToString(nFail) | ' cube(s) failed to copy ' | pSource | ' -> ' | pTarget | ': ' | vFailed);
    ProcessError;
  ENDIF;
ELSE;
  # Child: drop the temporary views and subsets.
  IF(ViewExists(pCube, cSrcView) = 1); ViewDestroy(pCube, cSrcView); ENDIF;
  IF(ViewExists(pCube, cTgtView) = 1); ViewDestroy(pCube, cTgtView); ENDIF;
  IF(SubsetExists(cVer, cSrcSub) = 1); SubsetDestroy(cVer, cSrcSub); ENDIF;
  IF(SubsetExists(cVer, cTgtSub) = 1); SubsetDestroy(cVer, cTgtSub); ENDIF;
  CubeSetLogChanges(pCube, 1);
ENDIF;
